int f(int x, int y){
int a = 0;
int b = 0;
int p = 0;
int q = 0;
int r = 0;
int s = 0;
if ((x >= 1) && (y >= 1))
{
  a = x;
  b = y;
  p = 1;
  q = 0;
  r = 0;
  s = 1;
  while (b == ((x * q) + (y * s)))
  {
    if (a > b)
    {
      a = a - b;
      p = p - q;
      r = r - s;
    }
    else
    {
      b = b - a;
      q = q - p;
      s = s - r;
    }
  }

}

return 0;
}
